use vstd::prelude::*;
use vstd::vec::Vec;

verus! {

fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
    ensures
        // The result has the same length as the input
        result.len() == m.len() &&
        // For every index i in [0, m.len()), result[i] == m[m.len() - 1 - i]
        forall |i: usize| i < m.len() ==> result[i] == m[m.len() - 1 - i]
{
    let n = m.len();
    let mut res: Vec<f32> = Vec::new();
    let mut i: usize = 0;
    while i < n
        invariant
            // i never exceeds n
            i <= n,
            // res has length i at each step
            res.len() == i,
            // For all j < i, res[j] == m[n - 1 - j]
            forall |j: usize| j < i ==> res[j] == m[n - 1 - j],
        decreases n - i,
    {
        // take the element from the end of m at position n - 1 - i
        let e: f32 = m[n - 1 - i];
        res.push(e);
        i += 1;
    }
    res
}

fn main() {
    // example usages
    let v0: Vec<f32> = Vec::new();
    assert(flipud(v0.clone()) == v0);

    let mut v1 = Vec::new();
    v1.push(1.0);
    let r1 = flipud(v1.clone());
    assert(r1.len() == 1);
    assert(r1[0] == 1.0);

    let mut v2 = Vec::new();
    v2.push(1.0);
    v2.push(2.5);
    v2.push(3.5);
    let r2 = flipud(v2.clone());
    assert(r2.len() == 3);
    assert(r2[0] == 3.5);
    assert(r2[1] == 2.5);
    assert(r2[2] == 1.0);
}

} // verus!